BEGIN;
CREATE TABLE IF NOT EXISTS league_behavior_profiles(id BIGSERIAL PRIMARY KEY,league_id VARCHAR(50) NOT NULL,draft_id VARCHAR(50) NOT NULL,pick_count INTEGER NOT NULL,room_type VARCHAR(30) NOT NULL,rb_rate NUMERIC(6,2) NOT NULL,wr_rate NUMERIC(6,2) NOT NULL,qb_rate NUMERIC(6,2) NOT NULL,te_rate NUMERIC(6,2) NOT NULL,confidence NUMERIC(6,2) NOT NULL,total_observations INTEGER NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(draft_id,pick_count));
CREATE TABLE IF NOT EXISTS owner_tendencies(id BIGSERIAL PRIMARY KEY,league_id VARCHAR(50) NOT NULL,draft_id VARCHAR(50) NOT NULL,pick_count INTEGER NOT NULL,owner_id VARCHAR(50) NOT NULL,owner_name TEXT,draft_slot INTEGER,preferred_strategy VARCHAR(50) NOT NULL,confidence NUMERIC(6,2) NOT NULL,observations INTEGER NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(draft_id,pick_count,owner_id));
CREATE TABLE IF NOT EXISTS position_run_history(id BIGSERIAL PRIMARY KEY,league_id VARCHAR(50) NOT NULL,draft_id VARCHAR(50) NOT NULL,snapshot_pick_count INTEGER NOT NULL,position VARCHAR(10) NOT NULL,start_pick INTEGER NOT NULL,end_pick INTEGER NOT NULL,run_length INTEGER NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(draft_id,snapshot_pick_count,position,start_pick,end_pick));
CREATE TABLE IF NOT EXISTS owner_pick_history(id BIGSERIAL PRIMARY KEY,league_id VARCHAR(50) NOT NULL,draft_id VARCHAR(50) NOT NULL,owner_id VARCHAR(50) NOT NULL,owner_name TEXT,roster_id INTEGER,draft_slot INTEGER,pick_number INTEGER NOT NULL,round_num INTEGER,player_name TEXT NOT NULL,position VARCHAR(10) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(draft_id,pick_number));
CREATE TABLE IF NOT EXISTS league_pressure_snapshots(id BIGSERIAL PRIMARY KEY,league_id VARCHAR(50) NOT NULL,draft_id VARCHAR(50) NOT NULL,pick_count INTEGER NOT NULL,next_pick INTEGER,position_pressure JSONB NOT NULL DEFAULT '{}'::jsonb,teams_needing_position JSONB NOT NULL DEFAULT '{}'::jsonb,projected_gone JSONB NOT NULL DEFAULT '{}'::jsonb,source VARCHAR(50),pre_draft_caution BOOLEAN NOT NULL DEFAULT FALSE,payload JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(draft_id,pick_count));
CREATE INDEX IF NOT EXISTS league_behavior_profiles_league_idx ON league_behavior_profiles(league_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS owner_tendencies_draft_idx ON owner_tendencies(draft_id,pick_count);
CREATE INDEX IF NOT EXISTS position_run_history_draft_idx ON position_run_history(draft_id,snapshot_pick_count);
CREATE INDEX IF NOT EXISTS owner_pick_history_owner_idx ON owner_pick_history(league_id,owner_id,pick_number);
CREATE INDEX IF NOT EXISTS league_pressure_snapshots_draft_idx ON league_pressure_snapshots(draft_id,pick_count);
COMMIT;
